} from "./state.ts";

import type { NormalizedTrackingStatus } from "./state.ts";

export function normalizeTrackingLabel(value: string): NormalizedTrackingStatus | null {
    const label = fold(value);
    if (!label) {
        return null;
    }
    if (
        mentionsRecipient(label) &&
        /\b(non|pas|impossible|refuse|refusee|refus|echec|echoue|annule|not|unable|failed|failure|refused|cancelled|canceled)\b/.test(
            label,
        )
    ) {
        return "incident";
    }
    if (recipientHandoffLabels.has(label)) {
        return "collected_by_recipient";
    }
    if (
        matches(label, [
            /remis (a|au) l expediteur/,
            /retourne (a|au) l expediteur/,
            /returned to (the )?sender/,
            /return delivered to (the )?sender/,
        ])
    ) {
        return "returned_to_sender";
    }
    if (
        matches(label, [
            /retour (a|vers) l expediteur/,
            /en cours de retour/,
            /retourne? vers l expediteur/,
            /returning to (the )?sender/,
            /return in progress/,
        ])
    ) {
        return "returning_to_sender";
    }
    if (
        matches(label, [
            /delai de retrait (est )?depasse/,
            /non retire/,
            /non reclame/,
            /instance expiree/,
            /pickup (period )?expired/,
            /not collected/,
        ])
    ) {
        return "pickup_expired";
    }
    if (matches(label, [/colis (est )?perdu/, /declare perdu/, /perte (du )?colis/, /parcel lost/, /shipment lost/])) {
        return "lost";
    }
    if (
        matches(label, [
            /avarie/,
            /anomalie/,
            /incident/,
            /endommage/,
            /adresse (incorrecte|incomplete)/,
            /refuse par (le )?destinataire/,
            /parcel damaged/,
            /delivery exception/,
        ])
    ) {
        return "incident";
    }
    if (
        matches(label, [
            /disponible (au|dans le|en) point relais/,
            /disponible (au|dans le) locker/,
            /mis(e)? a disposition (du )?destinataire/,
            /a disposition (du )?destinataire/,
            /pret a etre retire/,
            /ready for (collection|pickup)/,
            /available for (collection|pickup)/,
        ])
    ) {
        return "available_for_pickup";
    }
    if (
        matches(label, [
            /arrive (au|dans le) point relais/,
            /arrive (au|dans le) locker/,
            /livre (au|dans le) point relais/,
            /livre (au|dans le) locker/,
            /depose (au|dans le) point relais/,
            /arrived at (the )?(parcel shop|pickup point|locker)/,
            /delivered to (the )?(parcel shop|pickup point|locker)/,
        ])
    ) {
        return "arrived_at_pickup_point";
    }
    if (
        matches(label, [
            /remis a mondial relay/,
            /pris en charge par mondial relay/,
            /mondial relay a pris en charge/,
            /depose par l expediteur/,
            /handed to mondial relay/,
            /received by mondial relay/,
            /carrier accepted/,
        ])
    ) {
        return "carrier_accepted";
    }
    if (
        matches(label, [
            /en acheminement/,
            /en transit/,
            /en traitement (sur|au|dans)/,
            /site logistique/,
            /agence de livraison/,
            /transport vers/,
            /in transit/,
            /at (the )?(sorting|logistics) (site|center)/,
        ])
    ) {
        return "in_transit";
    }
    if (mentionsRecipient(label)) {
        return "incident";
    }
    return null;
}

const recipientHandoffLabels = new Set([
    "remis au destinataire",
    "colis remis au destinataire",
    "remis a son destinataire",
    "colis remis a son destinataire",
    "livre au destinataire",
    "colis livre au destinataire",
    "retire par le destinataire",
    "colis retire par le destinataire",
    "collected by the recipient",
    "collected by recipient",
    "delivered to the recipient",
    "delivered to recipient",
    "shipment delivered successfully to the recipient",
]);

function mentionsRecipient(value: string): boolean {
    return /\b(destinataire|recipient|consignee|customer)\b/.test(value);
}

function fold(value: string): string {
    return value
        .normalize("NFD")
        .replace(/[\u0300-\u036f]/g, "")
        .toLowerCase()
        .replace(/[^a-z0-9]+/g, " ")
        .trim();
}

function matches(value: string, patterns: RegExp[]): boolean {
    return patterns.some((pattern) => pattern.test(value));
}

import type { JsonRecord } from "../../shipment/types.ts";

export function providerOccurredAt(event: JsonRecord): string | null {
    const date = String(event.event_date ?? "");
    if (!/^\d{4}-\d{2}-\d{2}$/.test(date)) {
        return null;
    }
    const timeMatch = String(event.event_time ?? "00:00")
        .replace(/h/i, ":")
        .match(/^(\d{2}):(\d{2})/);
    const [year, month, day] = date.split("-").map(Number);
    const hour = Number(timeMatch?.[1] ?? 0);
    const minute = Number(timeMatch?.[2] ?? 0);
    if (![year, month, day, hour, minute].every(Number.isFinite)) {
        return null;
    }
    const wallClockUtc = Date.UTC(year, month - 1, day, hour, minute);
    const offset = parisOffsetMinutes(new Date(wallClockUtc));
    return new Date(wallClockUtc - offset * 60_000).toISOString();
}

export function trackingEventKey(expeditionNumber: string, event: JsonRecord): string {
    return [
        "mondial-relay",
        expeditionNumber,
        event.event_date,
        event.event_time,
        event.event_label,
        event.location,
        event.relay_country,
        event.relay_number,
    ]
        .map((value) => String(value ?? "").trim())
        .join("|");
}

function parisOffsetMinutes(date: Date): number {
    const zone =
        new Intl.DateTimeFormat("en", {
            timeZone: "Europe/Paris",
            timeZoneName: "shortOffset",
            year: "numeric",
        })
            .formatToParts(date)
            .find((part) => part.type === "timeZoneName")?.value ?? "GMT+1";
    const match = zone.match(/GMT([+-])(\d{1,2})(?::(\d{2}))?/);
    if (!match) {
        return 60;
    }
    const minutes = Number(match[2]) * 60 + Number(match[3] ?? 0);
    return match[1] === "-" ? -minutes : minutes;
}

export const normalizedStatuses = [
    "carrier_accepted",
    "in_transit",
    "arrived_at_pickup_point",
    "available_for_pickup",
    "collected_by_recipient",
    "incident",
    "lost",
    "pickup_expired",
    "returning_to_sender",
    "returned_to_sender",
] as const;

export type NormalizedTrackingStatus = (typeof normalizedStatuses)[number];

const terminalStatuses = new Set<string>(["collected_by_recipient", "lost", "returned_to_sender", "cancelled"]);

const forwardRank: Record<string, number> = {
    creating: 0,
    created: 1,
    label_ready: 2,
    carrier_accepted: 3,
    in_transit: 4,
    arrived_at_pickup_point: 5,
    available_for_pickup: 6,
    collected_by_recipient: 7,
};

export function fallbackTrackingStatus(statusCode: string): string {
    if (statusCode === "80") {
        return "created";
    }
    if (statusCode === "81") {
        return "in_transit";
    }
    if (statusCode === "82") {
        return "arrived_at_pickup_point";
    }
    return "incident";
}

export function statusAfterObservation(current: string, observed: string): string {
    if (!observed || current === observed || terminalStatuses.has(current)) {
        return current;
    }
    if (observed === "returned_to_sender" || observed === "lost" || observed === "collected_by_recipient") {
        return observed;
    }
    if (current === "pickup_expired") {
        return observed === "returning_to_sender" ? observed : current;
    }
    if (current === "returning_to_sender") {
        return current;
    }
    if (observed === "returning_to_sender" || observed === "pickup_expired" || observed === "incident") {
        return observed;
    }
    if (current === "incident") {
        return observed;
    }
    const currentRank = forwardRank[current] ?? 0;
    const observedRank = forwardRank[observed] ?? 0;
    return observedRank >= currentRank ? observed : current;
}

import { requiredEnv } from "../env.ts";
import { ProviderStatusError } from "../http.ts";
import { md5 } from "./md5.ts";
import { mondialRelayTrackingEndpoint } from "./provider-endpoints.ts";
import {
    fallbackTrackingStatus,
    normalizeTrackingLabel,
    providerOccurredAt,
    statusAfterObservation,
    trackingEventKey,
} from "./tracking-status/index.ts";
import type { JsonRecord } from "../shipment/types.ts";
import { xmlBlocks, xmlEscape, xmlTag } from "./xml.ts";

export interface TrackingResult {
    status: string;
    statusCode: string;
    label: string;
    events: JsonRecord[];
    raw: JsonRecord;
}

export async function fetchTracking(expeditionNumber: string): Promise<TrackingResult> {
    const endpoint = mondialRelayTrackingEndpoint();
    const brand = requiredEnv("MONDIAL_RELAY_TRACKING_BRAND");
    const privateKey = requiredEnv("MONDIAL_RELAY_TRACKING_PRIVATE_KEY");
    const language = "FR";
    const security = md5(`${brand}${expeditionNumber}${language}${privateKey}`).toUpperCase();
    const response = await fetch(endpoint, {
        method: "POST",
        redirect: "manual",
        headers: {
            "content-type": "text/xml; charset=utf-8",
            soapaction: "http://www.mondialrelay.fr/webservice/WSI2_TracingColisDetaille",
        },
        body: `<?xml version="1.0" encoding="utf-8"?>
<soap:Envelope xmlns:xsi="http://www.w3.org/2001/XMLSchema-instance" xmlns:xsd="http://www.w3.org/2001/XMLSchema" xmlns:soap="http://schemas.xmlsoap.org/soap/envelope/">
  <soap:Body>
    <WSI2_TracingColisDetaille xmlns="http://www.mondialrelay.fr/webservice/">
      <Enseigne>${xmlEscape(brand)}</Enseigne>
      <Expedition>${xmlEscape(expeditionNumber)}</Expedition>
      <Langue>${language}</Langue>
      <Security>${security}</Security>
    </WSI2_TracingColisDetaille>
  </soap:Body>
</soap:Envelope>`,
    }).catch(() => {
        throw new ProviderStatusError(502, "Mondial Relay tracking request failed", trackingContext(false));
    });
    if (response.redirected || (response.status >= 300 && response.status < 400)) {
        throw new ProviderStatusError(502, "Mondial Relay tracking redirects are not allowed", trackingContext(false));
    }
    const source = await response.text();
    if (!response.ok) {
        throw new ProviderStatusError(
            502,
            `Mondial Relay tracking returned HTTP ${response.status}`,
            trackingContext(false),
        );
    }
    const statusCode = xmlTag(source, "STAT");
    if (!statusCode) {
        throw new ProviderStatusError(
            502,
            "Mondial Relay tracking returned an invalid response",
            trackingContext(false),
        );
    }
    if (!["80", "81", "82", "83"].includes(statusCode)) {
        throw new ProviderStatusError(
            502,
            `Mondial Relay tracking returned status ${statusCode}`,
            trackingContext(true, statusCode),
        );
    }
    const label = [xmlTag(source, "Libelle01"), xmlTag(source, "Libelle02")].filter(Boolean).join(" ");
    const events = xmlBlocks(source, "Tracing")
        .map((block) => ({
            event_label: xmlTag(block, "Libelle"),
            event_date: frenchDate(xmlTag(block, "Date")),
            event_time: xmlTag(block, "Heure") || undefined,
            location: xmlTag(block, "Emplacement") || undefined,
            relay_number: xmlTag(block, "Relais_Num") || undefined,
            relay_country: xmlTag(block, "Relais_Pays") || undefined,
            raw_event: {
                label: xmlTag(block, "Libelle"),
                date: xmlTag(block, "Date"),
                time: xmlTag(block, "Heure"),
                location: xmlTag(block, "Emplacement"),
            },
        }))
        .filter((event) => event.event_label)
        .map((event) => {
            const occurredAt = providerOccurredAt(event);
            const candidateStatus = normalizeTrackingLabel(String(event.event_label));
            const normalizedStatus =
                !occurredAt && (candidateStatus === "collected_by_recipient" || candidateStatus === "carrier_accepted")
                    ? null
                    : candidateStatus;
            return {
                ...event,
                normalized_status: normalizedStatus ?? undefined,
                occurred_at: occurredAt ?? undefined,
                provider_event_key: trackingEventKey(expeditionNumber, event),
            };
        });
    const summaryCandidate = normalizeTrackingLabel(label);
    const summaryStatus =
        summaryCandidate === "collected_by_recipient" || summaryCandidate === "carrier_accepted"
            ? null
            : summaryCandidate;
    const status = events
        .filter((event) => event.normalized_status)
        .sort(compareEvents)
        .reduce(
            (current, event) => statusAfterObservation(current, String(event.normalized_status)),
            summaryStatus ?? fallbackTrackingStatus(statusCode),
        );
    return {
        status,
        statusCode,
        label,
        events,
        raw: { statusCode, label },
    };
}

function compareEvents(left: JsonRecord, right: JsonRecord): number {
    return String(left.occurred_at ?? "").localeCompare(String(right.occurred_at ?? ""));
}

function frenchDate(value: string): string | undefined {
    const match = value.match(/^(\d{2})\/(\d{2})\/(\d{4})$/);
    return match ? `${match[3]}-${match[2]}-${match[1]}` : undefined;
}

function trackingContext(retrySafe: boolean, statusCode = ""): JsonRecord {
    return {
        operation: "WSI2_TracingColisDetaille",
        endpoint: mondialRelayTrackingEndpoint(),
        statusCode,
        retrySafe,
    };
}

export function xmlEscape(value: string): string {
    return value
        .replace(/&/g, "&amp;")
        .replace(/</g, "&lt;")
        .replace(/>/g, "&gt;")
        .replace(/"/g, "&quot;")
        .replace(/'/g, "&apos;");
}

export function decodeXml(value: string): string {
    return value
        .replace(/&lt;/g, "<")
        .replace(/&gt;/g, ">")
        .replace(/&quot;/g, '"')
        .replace(/&apos;/g, "'")
        .replace(/&amp;/g, "&");
}

export function xmlTag(source: string, tag: string): string {
    const escaped = tag.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
    const match = source.match(new RegExp(`<${escaped}>(.*?)</${escaped}>`, "s"));
    return decodeXml(match?.[1] ?? "");
}

export function xmlAttr(source: string, tag: string, attr: string): string {
    const escapedTag = tag.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
    const escapedAttr = attr.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
    const match = source.match(new RegExp(`<${escapedTag}\\b[^>]*\\b${escapedAttr}="([^"]*)"`, "s"));
    return decodeXml(match?.[1] ?? "");
}

export function xmlAttributes(source: string, tag: string): Array<Record<string, string>> {
    const escapedTag = tag.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
    return Array.from(source.matchAll(new RegExp(`<${escapedTag}\\b([^>]*)>`, "g"))).map((match) => {
        const attrs: Record<string, string> = {};
        for (const attr of (match[1] ?? "").matchAll(/\b([A-Za-z0-9_:-]+)="([^"]*)"/g)) {
            if (attr[1]) {
                attrs[attr[1]] = decodeXml(attr[2] ?? "");
            }
        }
        return attrs;
    });
}

export function xmlBlocks(source: string, tag: string): string[] {
    const escaped = tag.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
    return Array.from(source.matchAll(new RegExp(`<${escaped}>(.*?)</${escaped}>`, "gs"))).map(
        (match) => match[1] ?? "",
    );
}

import { HttpError } from "../http.ts";
import { stringValue } from "../shipment/payload/index.ts";
import type { JsonRecord } from "../shipment/types.ts";

export function requiredBodyText(body: JsonRecord, name: string, maxLength: number): string {
    const value = stringValue(body[name]);
    if (!value) {
        throw new HttpError(400, `${name} is required`);
    }
    if (value.length > maxLength) {
        throw new HttpError(400, `${name} is too long`);
    }
    return value;
}

export function requiredBodyInteger(body: JsonRecord, name: string): number {
    const value = Number(body[name]);
    if (!Number.isSafeInteger(value) || value < 1) {
        throw new HttpError(400, `${name} must be a positive safe integer`);
    }
    return value;
}

