        events: detail.events,
    };
}

export function toShipmentJson(row: JsonRecord): JsonRecord {
    const out = camelizeRecord(row);
    if (typeof out.deliveryRelayNumber === "string") {
        out.deliveryRelayLocation = out.deliveryRelayNumber;
    }
