import { HttpError, json, limitParam, offsetParam, queryText, requireCmsRequest, requiredQuery } from "../../http.ts";
import { readShipmentTrackingContext } from "../../shipment/tracking-context.ts";
import {
    shipmentSelect,
    shipmentsRows,
    shipmentWithEventsRowByExpedition,
    shipmentWithEventsRowByExternalOrderId,
    shipmentWithEventsRowById,
} from "../../shipment/supabase/index.ts";
import type { JsonRecord } from "../../shipment/types.ts";
import { shipmentDetailJson, shipmentTrackingJson, toShipmentJson, trackingJson } from "./presentation.ts";

export async function shipments(request: Request): Promise<Response> {
    requireCmsRequest(request);
    const url = new URL(request.url);
    const limit = limitParam(url, 50);
    const offset = offsetParam(url);
    const filters = [
        `select=${encodeURIComponent(shipmentSelect())}`,
        `order=${encodeURIComponent("created_at.desc")}`,
        `limit=${limit}`,
        `offset=${offset}`,
    ];
    appendEqualFilter(filters, "status", queryText(url, "status"));
    appendEqualFilter(filters, "external_order_id", queryText(url, "externalOrderId"));
    const q = queryText(url, "q");
    if (q) {
        const value = q.replace(/[,*()]/g, " ").trim();
        if (value) {
            filters.push(
                `or=${encodeURIComponent(
                    [
                        `recipient_name.ilike.*${value}*`,
                        `recipient_city.ilike.*${value}*`,
                        `expedition_number.ilike.*${value}*`,
                        `external_order_id.ilike.*${value}*`,
                    ].join(","),
                )}`,
            );
        }
    }
    const rows = await shipmentsRows(filters.join("&"));
    return json({ items: rows.map(toShipmentJson), limit, offset });
}

export async function shipment(request: Request): Promise<Response> {
    requireCmsRequest(request);
    const url = new URL(request.url);
    const row = await shipmentWithEventsByRequest(url);
    if (!row) {
        throw new HttpError(404, "shipment not found");
    }
    return json(shipmentDetailJson(row));
}

export async function shipmentForExternalOrder(request: Request): Promise<Response> {
    requireCmsRequest(request);
    const externalOrderId = requiredQuery(new URL(request.url), "externalOrderId");
    const row = await shipmentWithEventsRowByExternalOrderId(externalOrderId);
    return json({ items: row ? [shipmentTrackingJson(row)] : [] });
}

export async function systemShipmentTrackingContext(request: Request): Promise<Response> {
    requireCmsRequest(request);
    const url = new URL(request.url);
    const expeditionNumber = requiredQuery(url, "expeditionNumber");
    const expectedExternalOrderId = requiredQuery(url, "expectedExternalOrderId");
    const context = await readShipmentTrackingContext(expeditionNumber, expectedExternalOrderId);
    return json({
        shipment: shipmentDetailJson(context.shipment),
        tracking: trackingJson(expeditionNumber, context.tracking, context.events),
    });
}

async function shipmentWithEventsByRequest(url: URL): Promise<JsonRecord | null> {
    const id = queryText(url, "id");
    if (id) {
        return await shipmentWithEventsRowById(id);
    }
    const expeditionNumber = queryText(url, "expeditionNumber");
    if (expeditionNumber) {
        return await shipmentWithEventsRowByExpedition(expeditionNumber);
    }
    throw new HttpError(400, "id or expeditionNumber is required");
}

function appendEqualFilter(filters: string[], name: string, value: string | undefined): void {
    if (value) {
        filters.push(`${name}=eq.${encodeURIComponent(value)}`);
    }
}

import { HttpError, json, requireCmsRequest, requiredQuery } from "../http.ts";
import { trackingSummaryContextByExpedition } from "../shipment/read-contexts.ts";
import { reconcileShipment, trackingRefreshDue } from "../shipment/reconciliation/index.ts";
import { shipmentEvents, shipmentRowByExpedition } from "../shipment/supabase/index.ts";
import type { JsonRecord } from "../shipment/types.ts";
import { publicTrackingEvent, trackingJson } from "./shipments/presentation.ts";

export async function tracking(request: Request): Promise<Response> {
    requireCmsRequest(request);
    const url = new URL(request.url);
    const expeditionNumber = requiredQuery(url, "expeditionNumber");
    const row = await shipmentRowByExpedition(expeditionNumber);
    if (!row) {
        throw new HttpError(404, "shipment not found");
    }
    if (trackingRefreshDue(row)) {
        const synchronized = await reconcileShipment(row);
        Object.assign(row, {
            status: synchronized.status,
            latest_event_label: synchronized.latestEventLabel ?? row.latest_event_label,
            latest_event_at: synchronized.latestEventAt ?? row.latest_event_at,
            carrier_accepted_at: synchronized.carrierAcceptedAt,
            recipient_handoff_at: synchronized.recipientHandoffAt,
            tracking_checked_at: synchronized.checkedAt,
        });
    }
    const events = await shipmentEvents(String(row.id));
    return json(trackingJson(expeditionNumber, row, events));
}

export async function parseTrackingLink(request: Request): Promise<Response> {
    requireCmsRequest(request);
    const url = new URL(request.url);
    const link = requiredQuery(url, "url");
    const parsed = parseMondialRelayTrackingLink(link);
    if (!parsed.expeditionNumber) {
        throw new HttpError(400, "unable to extract Mondial Relay expedition number");
    }
    return json({ ...parsed, tracking: await trackingSummary(parsed.expeditionNumber) });
}

async function trackingSummary(expeditionNumber: string): Promise<JsonRecord> {
    const context = await trackingSummaryContextByExpedition(expeditionNumber);
    const row = context.shipment;
    if (!row) {
        return { expeditionNumber, status: "unknown", events: [] };
    }
    return {
        expeditionNumber,
        status: row.status ?? "created",
        latestEventLabel: row.latest_event_label ?? "",
        latestEventAt: row.latest_event_at ?? "",
        events: context.events.map(publicTrackingEvent),
    };
}

function parseMondialRelayTrackingLink(value: string): JsonRecord {
    const url = new URL(value);
    const expeditionNumber =
        url.searchParams.get("numeroExpedition") ??
        url.searchParams.get("expedition") ??
        url.pathname.match(/(\d{8,})/)?.[1] ??
        "";
    const postalCode = url.searchParams.get("codePostal") ?? url.searchParams.get("cp") ?? "";
    return {
        carrier: "mondial-relay",
        expeditionNumber,
        postalCode,
        url: value,
    };
}

import { HttpError, isRecord } from "../http.ts";
import { labelAccessContext } from "./read-contexts.ts";
import { issueLabelAccessToken } from "./supabase/index.ts";
import type { JsonRecord } from "./types.ts";

const tokenLifetimeMs = 10 * 60 * 1000;
const contextFunction = "get_label_access_context";

export async function issueLabelCapability(
    externalOrderId: string,
    sellerCmsUserId: string,
): Promise<{ token: string; expiresAt: string }> {
    if (!externalOrderId || !sellerCmsUserId) {
        throw new HttpError(400, "externalOrderId and sellerCmsUserId are required");
    }
    const token = randomToken();
    const expiresAt = new Date(Date.now() + tokenLifetimeMs).toISOString();
    await issueLabelAccessToken(externalOrderId, sellerCmsUserId, await sha256(token), expiresAt);
    return { token, expiresAt };
}

export async function shipmentForLabelCapability(token: string, sellerCmsUserId: string): Promise<JsonRecord> {
    if (!token || !sellerCmsUserId) {
        throw new HttpError(401, "a seller-bound label token is required");
    }
    const context = await labelAccessContext(await sha256(token), sellerCmsUserId);
    if (!validState(context)) {
        throw invalidContext();
    }
    if (context.state === "not_found") {
        throw new HttpError(404, "label token not found");
    }
    if (context.state === "expired") {
        throw new HttpError(410, "label token expired");
    }
    if (context.state === "label_missing") {
        throw new HttpError(404, "label not found");
    }
    if (!validShipmentContext(context)) {
        throw invalidContext();
    }
    return context.shipment;
}

function validState(value: unknown): value is JsonRecord & { state: string } {
    if (!isRecord(value) || typeof value.state !== "string") {
        return false;
    }
    if (["not_found", "expired", "label_missing"].includes(value.state)) {
        return exactKeys(value, ["state"]);
    }
    return value.state === "ok" && exactKeys(value, ["state", "shipment"]);
}

function validShipmentContext(value: JsonRecord): value is JsonRecord & { shipment: JsonRecord } {
    if (!isRecord(value.shipment) || !exactKeys(value.shipment, ["expedition_number", "label_url"])) {
        return false;
    }
    return (
        (typeof value.shipment.expedition_number === "string" || value.shipment.expedition_number === null) &&
        typeof value.shipment.label_url === "string" &&
        value.shipment.label_url.length > 0
    );
}

function exactKeys(value: JsonRecord, expected: string[]): boolean {
    const keys = Object.keys(value).sort();
    return keys.length === expected.length && expected.every((key) => keys.includes(key));
}

function invalidContext(): HttpError {
    return new HttpError(502, `${contextFunction} returned an invalid response`);
}

async function sha256(value: string): Promise<string> {
    const digest = await crypto.subtle.digest("SHA-256", new TextEncoder().encode(value));
    return Array.from(new Uint8Array(digest))
        .map((byte) => byte.toString(16).padStart(2, "0"))
        .join("");
}

function randomToken(): string {
    const bytes = crypto.getRandomValues(new Uint8Array(32));
    let binary = "";
    for (const byte of bytes) {
        binary += String.fromCharCode(byte);
    }
    return btoa(binary).replace(/\+/g, "-").replace(/\//g, "_").replace(/=+$/g, "");
}

import { isRecord } from "../../http.ts";
import type { Address, JsonRecord } from "../types.ts";
import { phoneValue, stringValue } from "./values.ts";

export function addressFrom(body: JsonRecord, prefix: "sender" | "recipient", defaults: Address): Address {
    const source = isRecord(body[prefix]) ? (body[prefix] as JsonRecord) : {};
    const key = (name: string) => `${prefix}${name.charAt(0).toUpperCase()}${name.slice(1)}`;
    const field = (...aliases: string[]) => {
        for (const alias of aliases) {
            if (Object.prototype.hasOwnProperty.call(source, alias)) {
                return { supplied: true, value: source[alias] };
            }
        }
        for (const alias of aliases) {
            const flatKey = key(alias);
            if (Object.prototype.hasOwnProperty.call(body, flatKey)) {
                return { supplied: true, value: body[flatKey] };
            }
        }
        return { supplied: false, value: undefined };
    };
    const text = (fallback: string, ...aliases: string[]) => {
        const input = field(...aliases);
        return { supplied: input.supplied, value: stringValue(input.supplied ? input.value : fallback) };
    };
    const nameInput = text(defaults.name, "name");
    const firstNameInput = text(defaults.firstName, "firstName", "firstname");
    const lastNameInput = text(defaults.lastName, "lastName", "lastname");
    const name = nameInput.value;
    const firstName = firstNameInput.value;
    const lastName = lastNameInput.value;
    const split = splitName(name);
    const country = text(defaults.country, "country").value.toUpperCase();
    const phone = field("phone", "phoneNo");
    const mobile = field("mobile", "mobileNo");
    return {
        name,
        firstName: firstNameInput.supplied ? firstName : firstName || split.firstName,
        lastName: lastNameInput.supplied ? lastName : lastName || split.lastName,
        addressLine1: text(defaults.addressLine1, "addressLine1", "address1").value,
        addressLine2: text(defaults.addressLine2, "addressLine2", "address2").value,
        addressLine3: text(defaults.addressLine3, "addressLine3", "address3").value,
        city: text(defaults.city, "city").value,
        postalCode: text(defaults.postalCode, "postalCode", "postal_code").value,
        country,
        phone: phoneValue(phone.supplied ? phone.value : defaults.phone, "", country, `${prefix}.phone`),
        mobile: phoneValue(mobile.supplied ? mobile.value : defaults.mobile, "", country, `${prefix}.mobile`),
        email: text(defaults.email, "email").value,
    };
}

function splitName(name: string): { firstName: string; lastName: string } {
    const parts = name.trim().split(/\s+/).filter(Boolean);
    if (parts.length <= 1) {
        return { firstName: parts[0] || "Customer", lastName: parts[0] || "Customer" };
    }
    return { firstName: parts.slice(0, -1).join(" "), lastName: parts.at(-1) || "" };
}

export function splitStreet(addressLine: string): { houseNo: string; streetName: string } {
    const match = addressLine.trim().match(/^(\d+[A-Za-z]?)\s+(.+)$/);
    if (!match) {
        return { houseNo: "", streetName: addressLine.trim() };
    }
    return { houseNo: match[1] ?? "", streetName: match[2] ?? addressLine.trim() };
}

import { isRecord } from "../../http.ts";
