import { HttpError } from "../../http.ts";
import type { Address, ShipmentPayload } from "../types.ts";

export function validateShipmentPayload(payload: ShipmentPayload): void {
    if (!payload.externalOrderId) {
        throw new HttpError(400, "externalOrderId is required for protected fulfillment");
    }
    if (!["REL", "CCC"].includes(payload.modeCollection)) {
        throw new HttpError(400, "modeCollection must be REL or CCC for Mondial Relay Connect France");
    }
    if (payload.modeDelivery !== "24R") {
        throw new HttpError(400, "modeDelivery must be 24R for Mondial Relay Connect France");
    }
    if (!/^[A-Z0-9]{1,9}$/.test(payload.customerReference)) {
        throw new HttpError(400, "customerReference must contain 1 to 9 uppercase letters or digits");
    }
    requireFrance(payload.sender.country, "sender.country");
    requireFrance(payload.recipient.country, "recipient.country");
    requireFrance(payload.deliveryRelayCountry, "deliveryRelayLocation");
    requireAddress(payload.sender, "sender");
    requireAddress(payload.recipient, "recipient");
    if (payload.weightGrams < 1) {
        throw new HttpError(400, "weightGrams must be positive");
    }
    if (payload.packageCount !== 1) {
        throw new HttpError(400, "packageCount must be 1 for protected single-parcel fulfillment");
    }
    for (const [name, value] of [
        ["lengthCm", payload.lengthCm],
        ["widthCm", payload.widthCm],
        ["heightCm", payload.heightCm],
    ] as const) {
        if (value < 1) {
            throw new HttpError(400, `${name} must be positive`);
        }
    }
    validateMoney(payload.declaredValue, payload.declaredCurrency, "declaredValue");
    if (payload.declaredCurrency !== "EUR") {
        throw new HttpError(400, "declaredValue.currency must be EUR");
    }
}

function requireAddress(address: Address, label: string): void {
    for (const field of ["name", "addressLine1", "city", "postalCode", "country"] as const) {
        if (!address[field]) {
            throw new HttpError(400, `${label}.${field} is required`);
        }
    }
    validateFrenchPostalCode(address.postalCode, `${label}.postalCode`);
    validateInternationalPhone(address.phone, `${label}.phone`);
    validateInternationalPhone(address.mobile, `${label}.mobile`);
}

function requireFrance(value: string, name: string): void {
    if (value !== "FR") {
        throw new HttpError(400, `${name} must be FR for Mondial Relay Connect France`);
    }
}

function validateFrenchPostalCode(value: string, name: string): void {
    if (!/^\d{5}$/.test(value)) {
        throw new HttpError(400, `${name} must be 5 digits for FR`);
    }
}

function validateMoney(value: string, currency: string, name: string): void {
    const amount = Number(value);
    if (!Number.isFinite(amount) || amount < 0) {
        throw new HttpError(400, `${name}.value must be a non-negative number`);
    }
    if (amount > 0 && !currency) {
        throw new HttpError(400, `${name}.currency is required when ${name}.value is greater than 0`);
    }
    if (currency && !/^[A-Z]{3}$/.test(currency)) {
        throw new HttpError(400, `${name}.currency must be a 3-letter currency code`);
    }
}

function validateInternationalPhone(value: string, name: string): void {
    if (value && !/^\+[1-9]\d{7,14}$/.test(value)) {
        throw new HttpError(400, `${name} must use E.164 international format`);
    }
}

import { HttpError, isRecord } from "../../http.ts";
import type { JsonRecord } from "../types.ts";

export function relayLocation(body: JsonRecord): string {
    const explicit = stringValue(body.deliveryRelayLocation ?? nested(body, "deliveryRelay", "location")).toUpperCase();
    if (/^[A-Z]{2}-[A-Z0-9]{3,10}$/.test(explicit)) {
        return explicit;
    }
    const number = stringValue(body.deliveryRelayNumber ?? nested(body, "deliveryRelay", "number")).toUpperCase();
    const country = (
        stringValue(body.deliveryRelayCountry ?? nested(body, "deliveryRelay", "country")) || "FR"
    ).toUpperCase();
    if (number) {
        return number.includes("-") ? number : `${country}-${number}`;
    }
    throw new HttpError(400, "deliveryRelayLocation is required for 24R pickup point delivery");
}

export function stringValue(value: unknown): string {
    if (typeof value === "string") {
        return value.trim();
    }
    if (typeof value === "number" && Number.isFinite(value)) {
        return String(value);
    }
    return "";
}

export function normalizePhone(value: string, country = "FR"): string {
    const raw = value.trim();
    if (!raw) {
        return "";
    }
    let text = raw.replace(/\(0\)/g, "").replace(/[\s.()/\-]/g, "");
    if (text.startsWith("00")) {
        text = `+${text.slice(2)}`;
    }
    if (!text.startsWith("+")) {
        const digits = text.replace(/\D/g, "");
        if (!digits) {
            return "";
        }
        if (country.toUpperCase() === "FR") {
            if (/^0[1-9]\d{8}$/.test(digits)) {
                return `+33${digits.slice(1)}`;
            }
            if (/^33[1-9]\d{8}$/.test(digits)) {
                return `+${digits}`;
            }
        }
        return `+${digits}`;
    }

    text = `+${text.slice(1).replace(/\D/g, "")}`;
    if (country.toUpperCase() === "FR" && /^\+330[1-9]\d{8}$/.test(text)) {
        return `+33${text.slice(4)}`;
    }
    return text;
}

export function integerValue(value: unknown, name: string): number {
    const text = stringValue(value);
    const number = Number(text);
    if (!Number.isInteger(number)) {
        throw new HttpError(400, `${name} must be an integer`);
    }
    return number;
}

export function minorAmount(value: unknown, name: string): number {
    const text = stringValue(value);
    const amount = Number(text);
    if (!Number.isSafeInteger(amount) || amount < 0 || amount > 999_999_999) {
        throw new HttpError(400, `${name} must be an integer between 0 and 999999999 minor units`);
    }
    return amount;
}

export function minorAmountText(value: unknown, name: string): string {
    const amount = minorAmount(value, name);
    const major = Math.floor(amount / 100);
    const minor = String(amount % 100).padStart(2, "0");
    const text = `${major}.${minor}`;
    if (!/^\d{1,7}\.\d{2}$/.test(text)) {
        throw new HttpError(400, `${name} exceeds the Mondial Relay limit`);
    }
    return text;
}

export function currencyText(value: unknown, fallback = "EUR"): string {
    return (stringValue(value) || fallback).toUpperCase();
}

export function nested(body: JsonRecord, first: string, second: string): unknown {
    const value = body[first];
    return isRecord(value) ? value[second] : undefined;
}

export function phoneValue(value: unknown, fallback: string, country: string, name: string): string {
    const raw = stringValue(value) || fallback;
    const normalized = normalizePhone(raw, country);
    if (raw && !normalized) {
        throw new HttpError(400, `${name} must use E.164 international format`);
    }
    return normalized;
}

import { HttpError, isRecord } from "../http.ts";
import { restJson } from "./supabase/index.ts";
import type { JsonRecord } from "./types.ts";

export type RelaySelectionContext =
    | { outcome: "selection" | "quote"; row: JsonRecord }
    | { outcome: "missing"; row: null };

export type RelaySelectionSetupContext =
    | { outcome: "shipment_exists"; settings: null }
    | { outcome: "ready"; settings: JsonRecord | null };

export type TrackingSummaryContext = {
    shipment: JsonRecord | null;
    events: JsonRecord[];
};

export async function labelAccessContext(tokenHash: string, sellerCmsUserId: string): Promise<unknown> {
    return await restJson<unknown>("rpc/get_label_access_context", {
        method: "POST",
        headers: { "content-type": "application/json" },
        body: JSON.stringify({
            p_token_hash: tokenHash,
            p_seller_cms_user_id: sellerCmsUserId,
        }),
    });
}

export async function readRelaySelectionContext(
    externalOrderId: string,
    selectedForCmsUserId: string,
): Promise<RelaySelectionContext> {
    let context: unknown;
    try {
        context = await restJson<unknown>("rpc/read_relay_selection_context", {
            method: "POST",
            headers: { "content-type": "application/json" },
            body: JSON.stringify({
                p_external_order_id: externalOrderId,
                p_selected_for_cms_user_id: selectedForCmsUserId || null,
            }),
        });
    } catch (error) {
        if (error instanceof SyntaxError) {
            throw invalidRelaySelectionContext();
        }
        throw error;
    }
    if (!isRecord(context)) {
        throw invalidRelaySelectionContext();
    }
    if (context.outcome === "missing" && context.row === null) {
        return { outcome: "missing", row: null };
    }
    if ((context.outcome === "selection" || context.outcome === "quote") && isRecord(context.row)) {
        return { outcome: context.outcome, row: context.row };
    }
    throw invalidRelaySelectionContext();
}

export async function readRelaySelectionSetupContext(
    externalOrderId: string,
    readSettings: boolean,
): Promise<RelaySelectionSetupContext> {
    let context: unknown;
    try {
        context = await restJson<unknown>("rpc/read_relay_selection_setup_context", {
            method: "POST",
            headers: { "content-type": "application/json" },
            body: JSON.stringify({
                p_external_order_id: externalOrderId,
                p_read_settings: readSettings,
            }),
        });
    } catch (error) {
        if (error instanceof SyntaxError) {
            throw invalidRelaySelectionSetupContext();
        }
        throw error;
    }
    if (!isRecord(context)) {
        throw invalidRelaySelectionSetupContext();
    }
    if (context.outcome === "shipment_exists" && context.settings === null) {
        return { outcome: "shipment_exists", settings: null };
    }
    if (context.outcome === "ready" && (context.settings === null || isRecord(context.settings))) {
        return { outcome: "ready", settings: context.settings };
    }
    throw invalidRelaySelectionSetupContext();
}

export async function trackingSummaryContextByExpedition(expeditionNumber: string): Promise<TrackingSummaryContext> {
    const value = await restJson<unknown>("rpc/read_tracking_summary", {
        method: "POST",
        headers: { "content-type": "application/json" },
        body: JSON.stringify({ p_expedition_number: expeditionNumber }),
    });
    const row = Array.isArray(value) && value.length === 1 ? value[0] : undefined;
    if (
        !isRecord(row) ||
        (row.shipment !== null && !isTrackingSummaryShipment(row.shipment)) ||
        !Array.isArray(row.events) ||
        !row.events.every(isTrackingSummaryEvent) ||
        (row.shipment === null && row.events.length > 0)
    ) {
        throw invalidTrackingSummaryContext();
    }
    return {
        shipment: row.shipment,
        events: row.events,
    };
}

function invalidRelaySelectionContext(): HttpError {
    return new HttpError(502, "relay selection context returned an invalid response");
}

function invalidRelaySelectionSetupContext(): HttpError {
    return new HttpError(502, "relay selection setup context returned an invalid response");
}

function isTrackingSummaryShipment(value: unknown): value is JsonRecord {
    return (
        isRecord(value) &&
        hasExactFields(value, ["id", "status", "latest_event_label", "latest_event_at"]) &&
        typeof value.id === "string" &&
        value.id.length > 0 &&
        typeof value.status === "string" &&
        isNullableString(value.latest_event_label) &&
        isNullableString(value.latest_event_at)
    );
}

function isTrackingSummaryEvent(value: unknown): value is JsonRecord {
    return (
        isRecord(value) &&
        hasExactFields(value, [
            "normalized_status",
            "occurred_at",
            "event_label",
            "event_date",
            "event_time",
            "location",
        ]) &&
        isNullableString(value.normalized_status) &&
        isNullableString(value.occurred_at) &&
        typeof value.event_label === "string" &&
        isNullableString(value.event_date) &&
        isNullableString(value.event_time) &&
        isNullableString(value.location)
    );
}

function hasExactFields(value: JsonRecord, fields: string[]): boolean {
    return Object.keys(value).length === fields.length && fields.every((field) => Object.hasOwn(value, field));
}

function isNullableString(value: unknown): value is string | null {
    return value === null || typeof value === "string";
}

function invalidTrackingSummaryContext(): HttpError {
    return new HttpError(502, "tracking summary context returned an invalid response");
}

import { claimShipmentsDueForTracking, pendingShipmentEvents, updateShipment } from "../supabase/index.ts";
import type { JsonRecord } from "../types.ts";
import { claimIdFromExternalOrderId, projectableClaimReturnEvent, projectableEvent } from "./projection-events.ts";
import { reconcileShipment } from "./shipment.ts";

export async function reconcileDueShipments(limit: number, workerId: string): Promise<JsonRecord> {
    const rows = await claimShipmentsDueForTracking(workerId, limit);
    const shipments: JsonRecord[] = [];
    for (const row of rows) {
        try {
            const result = await reconcileShipment(row);
            shipments.push(result);
        } catch (error) {
            const checkedAt = new Date().toISOString();
            await updateShipment(
                String(row.id),
                {
                    tracking_next_attempt_at: new Date(Date.now() + 15 * 60_000).toISOString(),
                    tracking_claimed_at: null,
                    tracking_claimed_by: null,
                    last_error: error instanceof Error ? error.message : "tracking reconciliation failed",
                },
                String(row.status),
            ).catch(() => null);
            shipments.push({
                id: row.id,
                externalOrderId: row.external_order_id,
                expeditionNumber: row.expedition_number,
                status: row.status,
                checkedAt,
                reconciliationError: true,
            });
        }
    }
    const pendingEvents = await pendingShipmentEvents(workerId, limit);
    const events = pendingEvents
        .filter((event) => !claimIdFromExternalOrderId(event.order_public_id))
        .map(projectableEvent);
    const claimReturnEvents = pendingEvents.flatMap((event) => {
        const claimId = claimIdFromExternalOrderId(event.order_public_id);
        return claimId ? [projectableClaimReturnEvent(event, claimId)] : [];
    });
    return { processed: rows.length, shipments, events, claimReturnEvents };
}

export { reconcileDueShipments } from "./batch.ts";
export { reconcileShipment } from "./shipment.ts";
export { trackingRefreshDue } from "./updates.ts";

import { normalizedStatuses } from "../../provider/tracking-status/index.ts";
import type { JsonRecord } from "../types.ts";

export function cancellationCarrierActivity(status: string): boolean {
    // Every normalized carrier observation is cancellation-blocking. In
    // particular, `incident` is also the fail-closed normalization for an
    // unknown STAT 83 response and for ambiguous/negative recipient labels.
    return (normalizedStatuses as readonly string[]).includes(status);
}

export function normalizedObservations(
    events: JsonRecord[],
    row: JsonRecord,
    summaryStatus: string,
    statusCode: string,
    label: string,
    checkedAt: string,
): JsonRecord[] {
    const normalized = events
        .filter((event) => event.normalized_status && event.occurred_at)
        .map((event) => ({
            orderPublicId: row.external_order_id,
            providerEventId: event.provider_event_key,
            normalizedStatus: event.normalized_status,
            occurredAt: event.occurred_at,
            providerReference: row.expedition_number,
            ...(event.normalized_status === "carrier_accepted" ? { carrierAcceptedAt: event.occurred_at } : {}),
            ...(event.normalized_status === "collected_by_recipient" ? { recipientHandoffAt: event.occurred_at } : {}),
        }));
    if (normalized.length || !commerceStatus(summaryStatus)) {
        return normalized;
    }
    return [
        {
            orderPublicId: row.external_order_id,
            providerEventId: `mondial-relay|${row.expedition_number}|summary|${statusCode}|${fold(label)}`,
            normalizedStatus: summaryStatus,
            occurredAt: checkedAt,
            providerReference: row.expedition_number,
        },
    ];
}

function commerceStatus(value: string): boolean {
    return [
        "carrier_accepted",
        "in_transit",
        "arrived_at_pickup_point",
        "available_for_pickup",
        "collected_by_recipient",
        "incident",
        "lost",
        "pickup_expired",
        "returning_to_sender",
        "returned_to_sender",
    ].includes(value);
}

export function milestonePatch(observations: JsonRecord[], row: JsonRecord): JsonRecord {
    const columns: Record<string, string> = {
        carrier_accepted: "carrier_accepted_at",
        arrived_at_pickup_point: "arrived_at_pickup_point_at",
        available_for_pickup: "available_for_pickup_at",
        collected_by_recipient: "recipient_handoff_at",
        pickup_expired: "pickup_expired_at",
        returning_to_sender: "returning_to_sender_at",
        returned_to_sender: "returned_to_sender_at",
        incident: "incident_at",
        lost: "lost_at",
    };
    const patch: JsonRecord = {};
    for (const observation of observations) {
        const column = columns[String(observation.normalizedStatus)];
        if (column && !row[column] && !patch[column]) {
            patch[column] = observation.occurredAt;
        }
    }
    return patch;
}

export function latestProviderEvent(events: JsonRecord[]): JsonRecord | null {
    return (
        [...events]
            .filter((event) => event.occurred_at)
            .sort((left, right) => String(left.occurred_at).localeCompare(String(right.occurred_at)))
            .at(-1) ?? null
    );
}

function fold(value: string): string {
    return value
        .normalize("NFD")
        .replace(/[\u0300-\u036f]/g, "")
        .toLowerCase()
        .replace(/[^a-z0-9]+/g, "-")
        .replace(/^-|-$/g, "")
        .slice(0, 80);
}

import type { JsonRecord } from "../types.ts";

export function projectableEvent(event: JsonRecord): JsonRecord {
    const normalizedStatus = String(event.normalized_status ?? "");
    const occurredAt = String(event.occurred_at ?? "");
    return {
        eventId: event.id,
        claimToken: event.projection_claim_token,
        projectionAttempts: event.projection_attempts,
        orderPublicId: event.order_public_id,
        providerEventId: event.provider_event_key,
        normalizedStatus,
        occurredAt,
        providerReference: event.expedition_number,
        ...(normalizedStatus === "carrier_accepted" ? { carrierAcceptedAt: occurredAt } : {}),
        ...(normalizedStatus === "collected_by_recipient" ? { recipientHandoffAt: occurredAt } : {}),
    };
}

export function projectableClaimReturnEvent(event: JsonRecord, claimId: number): JsonRecord {
    const providerStatus = String(event.normalized_status ?? "");
    const normalizedStatus = providerStatus === "collected_by_recipient" ? "recipient_handoff" : providerStatus;
    return {
        eventId: event.id,
        claimToken: event.projection_claim_token,
        projectionAttempts: event.projection_attempts,
        claimId,
        externalOrderId: event.order_public_id,
        providerEventId: event.provider_event_key,
        normalizedStatus,
        occurredAt: event.occurred_at,
        providerReference: event.expedition_number,
        providerEvidence: { provider: "mondial-relay", providerStatus },
    };
}

export function claimIdFromExternalOrderId(value: unknown): number | null {
    const match = /^claim-return:([1-9][0-9]*)$/.exec(String(value ?? ""));
    if (!match) {
        return null;
    }
    const claimId = Number(match[1]);
    return Number.isSafeInteger(claimId) ? claimId : null;
}

import { fetchTracking } from "../../provider/tracking.ts";
import { statusAfterObservation } from "../../provider/tracking-status/index.ts";
import { upsertShipmentEvents } from "../supabase/index.ts";
import type { JsonRecord } from "../types.ts";
import {
    cancellationCarrierActivity,
    latestProviderEvent,
    milestonePatch,
    normalizedObservations,
} from "./observations.ts";
import { optimisticShipmentUpdate } from "./updates.ts";

export async function reconcileShipment(row: JsonRecord): Promise<JsonRecord> {
    const expeditionNumber = String(row.expedition_number ?? "");
    if (!expeditionNumber) {
        throw new Error("shipment has no provider reference");
    }
    const checkedAt = new Date().toISOString();
    const result = await fetchTracking(expeditionNumber);
    const providerEvents = result.events.map((event) => ({
        ...event,
        shipment_id: row.id,
        order_public_id: row.external_order_id,
        expedition_number: expeditionNumber,
    }));
    const observations = normalizedObservations(
        providerEvents,
        row,
        result.status,
        result.statusCode,
        result.label,
        checkedAt,
    );
    const currentStatus = String(row.status ?? "created");
    const cancellationObservations =
        currentStatus === "cancelled_unscanned"
            ? observations.filter((observation) => cancellationCarrierActivity(String(observation.normalizedStatus)))
            : observations;
    const storedProviderEvents =
        currentStatus === "cancelled_unscanned"
            ? providerEvents.map((event) =>
                  cancellationCarrierActivity(String(event.normalized_status ?? ""))
                      ? event
                      : { ...event, normalized_status: undefined },
              )
            : providerEvents;
    const providerKeys = new Set(storedProviderEvents.map((event) => event.provider_event_key));
    const storedEvents = [
        ...storedProviderEvents,
        ...cancellationObservations
            .filter((observation) => !providerKeys.has(observation.providerEventId))
            .map((observation) => ({
                shipment_id: row.id,
                order_public_id: row.external_order_id,
                expedition_number: expeditionNumber,
                provider_event_key: observation.providerEventId,
                normalized_status: observation.normalizedStatus,
                occurred_at: observation.occurredAt,
                event_label: result.label || `Statut Mondial Relay ${result.statusCode}`,
                raw_event: { summary: true, statusCode: result.statusCode },
            })),
    ];
    await upsertShipmentEvents(storedEvents);

    let nextStatus = observations
        .sort((left, right) => String(left.occurredAt).localeCompare(String(right.occurredAt)))
        .reduce(
            (current, observation) => statusAfterObservation(current, String(observation.normalizedStatus)),
            statusAfterObservation(currentStatus, result.status),
        );
    if (currentStatus === "cancelled_unscanned") {
        const lateCarrierScan = cancellationObservations.length > 0;
        const trackingUntil = Date.parse(String(row.cancellation_tracking_until ?? ""));
        nextStatus = lateCarrierScan
            ? "manual_review"
            : Number.isFinite(trackingUntil) && Date.now() >= trackingUntil
              ? "cancelled"
              : "cancelled_unscanned";
    }
    const latest = latestProviderEvent(providerEvents);
    const patch: JsonRecord = {
        status: nextStatus,
        latest_event_label: result.label || latest?.event_label || null,
        latest_event_at: latest?.occurred_at || row.latest_event_at || null,
        tracking_checked_at: checkedAt,
        tracking_next_attempt_at: null,
        tracking_claimed_at: null,
        tracking_claimed_by: null,
        last_error:
            nextStatus === "manual_review" && currentStatus === "cancelled_unscanned"
                ? "carrier activity or ambiguity observed after local shipment cancellation"
                : null,
        raw_response: {
            ...record(row.raw_response),
            tracking: { ...result.raw, checkedAt },
        },
        ...milestonePatch(observations, row),
    };
    const updated = await optimisticShipmentUpdate(
        row,
        patch,
        observations.some((observation) => cancellationCarrierActivity(String(observation.normalizedStatus))),
    );
    return {
        id: updated.id,
        externalOrderId: updated.external_order_id,
        expeditionNumber,
        status: updated.status,
        latestEventLabel: updated.latest_event_label,
        latestEventAt: updated.latest_event_at,
        carrierAcceptedAt: updated.carrier_accepted_at,
        arrivedAtPickupPointAt: updated.arrived_at_pickup_point_at,
        availableForPickupAt: updated.available_for_pickup_at,
        recipientHandoffAt: updated.recipient_handoff_at,
        pickupExpiredAt: updated.pickup_expired_at,
        returningToSenderAt: updated.returning_to_sender_at,
        returnedToSenderAt: updated.returned_to_sender_at,
        incidentAt: updated.incident_at,
        lostAt: updated.lost_at,
        checkedAt,
        events: observations,
    };
}

function record(value: unknown): JsonRecord {
    return value && typeof value === "object" && !Array.isArray(value) ? (value as JsonRecord) : {};
}

import { statusAfterObservation } from "../../provider/tracking-status/index.ts";
import { shipmentRowById, updateShipment } from "../supabase/index.ts";
import type { JsonRecord } from "../types.ts";
import { cancellationCarrierActivity } from "./observations.ts";

export function trackingRefreshDue(row: JsonRecord): boolean {
    if (["collected_by_recipient", "lost", "returned_to_sender", "cancelled"].includes(String(row.status))) {
        return false;
    }
    const claimedAt = Date.parse(String(row.tracking_claimed_at ?? ""));
    if (Number.isFinite(claimedAt) && Date.now() - claimedAt < 20 * 60_000) {
        return false;
    }
    const nextAttemptAt = Date.parse(String(row.tracking_next_attempt_at ?? ""));
    if (Number.isFinite(nextAttemptAt) && Date.now() < nextAttemptAt) {
        return false;
    }
    const checkedAt = Date.parse(String(row.tracking_checked_at ?? ""));
    return !Number.isFinite(checkedAt) || Date.now() - checkedAt >= 4 * 60 * 60 * 1000;
}

export async function optimisticShipmentUpdate(
    row: JsonRecord,
    patch: JsonRecord,
    cancellationBlockingObservation: boolean,
): Promise<JsonRecord> {
    const id = String(row.id);
    const first = await updateShipment(id, patch, String(row.status));
    if (first) {
        return first;
    }
    const current = await shipmentRowById(id);
    if (!current) {
        throw new Error("shipment disappeared during reconciliation");
    }
    if (["cancelled_unscanned", "cancelled"].includes(String(current.status))) {
        if (cancellationBlockingObservation || cancellationCarrierActivity(String(patch.status))) {
            const retry = await updateShipment(
                id,
                {
                    ...patch,
                    status: "manual_review",
                    last_error: "carrier activity or ambiguity raced with local shipment cancellation",
                },
                String(current.status),
            );
            return retry ?? current;
        }
        // A reconciliation that started before cancellation must never restore
        // the pre-cancellation state when its compare-and-set loses the race.
        // Keep the cancellation decision and its audit fields verbatim while
        // releasing this worker's tracking lease and recording the safe check.
        const cancellationSafePatch = { ...patch };
        delete cancellationSafePatch.status;
        delete cancellationSafePatch.last_error;
        delete cancellationSafePatch.cancellation_tracking_until;
        const retry = await updateShipment(id, cancellationSafePatch, String(current.status));
        return retry ?? current;
    }
    const safeStatus = statusAfterObservation(String(current.status), String(patch.status));
    const retry = await updateShipment(id, { ...patch, status: safeStatus }, String(current.status));
    return retry ?? current;
}

