export async function declareSellerHandoff(externalOrderId: string, sellerCmsUserId: string): Promise<JsonRecord> {
    if (!externalOrderId) {
        throw new HttpError(400, "externalOrderId is required");
    }
    if (!sellerCmsUserId) {
        throw new HttpError(400, "seller CMS user id is required");
    }
    return handoffResult(await declareSellerHandoffRow(externalOrderId, sellerCmsUserId));
}

export async function cancelShipmentReservation(externalOrderId: string, trackingUntil: string): Promise<JsonRecord> {
    if (!externalOrderId || !trackingUntil) {
        throw new HttpError(400, "externalOrderId and trackingUntil are required");
    }
    return shipmentResult(await cancelShipmentUnscanned(externalOrderId, trackingUntil));
}

export async function recoverUnknownShipment(
    shipmentId: string,
    externalOrderId: string,
    expeditionNumber: string,
    labelUrl: string,
    actorCmsUserId: string,
    reason: string,
): Promise<JsonRecord> {
    if (!/^\d{8}$/.test(expeditionNumber)) {
        throw new HttpError(400, "expeditionNumber must contain 8 digits");
    }
    if (!actorCmsUserId || reason.trim().length < 8) {
        throw new HttpError(400, "an administrator and a recovery reason are required");
    }
    const row = await shipmentRowById(shipmentId);
    if (!row || row.external_order_id !== externalOrderId) {
        throw new HttpError(404, "exact shipment creation reservation not found");
    }
    if (["created", "label_ready"].includes(String(row.status)) && row.expedition_number === expeditionNumber) {
        return {
            ...shipmentResult(row),
            idempotentReplay: true,
        };
    }
    if (row.status !== "unknown") {
        throw new HttpError(409, "only an unknown shipment reservation can be recovered");
    }
    const validatedLabelUrl = labelUrl ? validatedMondialRelayLabelUrl(labelUrl).toString() : "";
    await insertShipmentRecoveryEvent({
        shipment_id: row.id,
        actor_cms_user_id: actorCmsUserId,
        reason: reason.trim(),
        previous_status: row.status,
        expedition_number: expeditionNumber,
    });
    const updated = await updateShipment(
        String(row.id),
        {
            expedition_number: expeditionNumber,
            tracking_number: expeditionNumber,
            status: validatedLabelUrl ? "label_ready" : "created",
            label_url: validatedLabelUrl || null,
            tracking_url: trackingUrl(expeditionNumber, String(row.recipient_postal_code ?? "")),
            last_error: null,
        },
        "unknown",
    );
    if (!updated) {
        throw new HttpError(409, "shipment state changed while applying recovery");
    }
    return shipmentResult(updated);
}

function handoffResult(row: JsonRecord): JsonRecord {
    return {
        ...shipmentResult(row),
        sellerHandoffDeclaredAt: row.seller_handoff_declared_at,
    };
}

function shipmentResult(row: JsonRecord): JsonRecord {
    return {
        id: row.id,
        externalOrderId: row.external_order_id,
        expeditionNumber: row.expedition_number,
        status: row.status,
        carrierAcceptedAt: row.carrier_accepted_at,
        recipientHandoffAt: row.recipient_handoff_at,
    };
}

function trackingUrl(expeditionNumber: string, postalCode: string): string {
    const url = new URL("https://www.mondialrelay.fr/suivi-de-colis/");
    url.searchParams.set("numeroExpedition", expeditionNumber);
    if (postalCode) {
        url.searchParams.set("codePostal", postalCode);
    }
    return url.toString();
}

import { envText } from "../../env.ts";
import { HttpError } from "../../http.ts";
import type { JsonRecord } from "../types.ts";

const deliverySchema = "delivery";

export async function getOne(
    table: string,
    filters: Record<string, string>,
    select: string,
): Promise<JsonRecord | null> {
    const params = [`select=${encodeURIComponent(select)}`, "limit=1"];
    for (const [key, value] of Object.entries(filters)) {
        params.push(`${encodeURIComponent(key)}=eq.${encodeURIComponent(value)}`);
    }
    const rows = await restJson<JsonRecord[]>(`${table}?${params.join("&")}`, { method: "GET" });
    return rows[0] ?? null;
}

export async function restJson<T>(path: string, init: RequestInit): Promise<T> {
    const response = await rest(path, init);
    const text = await response.text();
    return text ? (JSON.parse(text) as T) : (undefined as T);
}

async function rest(path: string, init: RequestInit): Promise<Response> {
    const base = envText("SUPABASE_URL");
    const key = supabaseDataApiKey();
    if (!base || !key) {
        throw new HttpError(500, "Supabase service credentials are not configured");
    }
    const headers = new Headers(init.headers);
    headers.set("apikey", key);
    if (key.startsWith("sb_")) {
        headers.delete("authorization");
    } else {
        headers.set("authorization", `Bearer ${key}`);
    }
    headers.set("accept-profile", deliverySchema);
    if (init.method && init.method !== "GET") {
        headers.set("content-profile", deliverySchema);
    }
    const response = await fetch(`${base}/rest/v1/${path}`, { ...init, headers });
    if (response.ok) {
        return response;
    }
    const detail = await response.text().catch(() => "");
    throw dataApiError(response.status, detail);
}

export function dataApiError(status: number, detail: string): HttpError {
    const message = postgresMessage(detail);
    if (message.startsWith("not_found: ")) {
        return new HttpError(404, message.slice("not_found: ".length));
    }
    if (message.startsWith("conflict: ")) {
        return new HttpError(409, message.slice("conflict: ".length));
    }
    if (message.startsWith("validation: ")) {
        return new HttpError(400, message.slice("validation: ".length));
    }
    return new HttpError(502, `Supabase Data API request failed (${status})`);
}

function postgresMessage(detail: string): string {
    if (!detail) {
        return "";
    }
    try {
        const parsed = JSON.parse(detail) as JsonRecord;
        return typeof parsed.message === "string" ? parsed.message : "";
    } catch {
        return "";
    }
}

function supabaseDataApiKey(): string {
    return supabaseSecretKeys()[0] ?? "";
}

function supabaseSecretKeys(): string[] {
    const keys: string[] = [];
    const secretKeys = envText("SUPABASE_SECRET_KEYS");
    if (secretKeys) {
        if (!secretKeys.startsWith("{")) {
            keys.push(
                ...secretKeys
                    .split(",")
                    .map((value) => value.trim())
                    .filter(Boolean),
            );
        } else {
            try {
                const parsed = JSON.parse(secretKeys);
                if (isRecord(parsed)) {
                    if (typeof parsed.default === "string" && parsed.default) {
                        keys.push(parsed.default);
                    }
                    for (const value of Object.values(parsed)) {
                        if (typeof value === "string" && value && value !== parsed.default) {
                            keys.push(value);
                        }
                    }
                }
            } catch {
                throw new HttpError(500, "SUPABASE_SECRET_KEYS must be valid JSON");
            }
        }
    }

    const modernSecretKey = envText("SUPABASE_SECRET_KEY");
    if (modernSecretKey) {
        keys.push(modernSecretKey);
    }
    const legacyServiceRoleKey = envText("SUPABASE_SERVICE_ROLE_KEY");
    if (legacyServiceRoleKey) {
        keys.push(legacyServiceRoleKey);
    }

    return [...new Set(keys)];
}

function isRecord(value: unknown): value is JsonRecord {
    return typeof value === "object" && value !== null && !Array.isArray(value);
}

