create or replace function delivery.fail_shipment_event_projection(
    p_event_id bigint,
    p_claim_token uuid,
    p_error text,
    p_retry_delay_seconds integer default 60,
    p_max_attempts integer default 5
)
returns jsonb
language plpgsql
set search_path = ''
as $$
declare
    v_event delivery.shipment_events%rowtype;
begin
    if p_error is null or length(btrim(p_error)) = 0 or p_retry_delay_seconds < 1
        or p_retry_delay_seconds > 86400 or p_max_attempts < 1 or p_max_attempts > 20 then
        raise exception 'validation: invalid projection failure';
    end if;
    select * into v_event from delivery.shipment_events
    where id = p_event_id for update;
    if not found then raise exception 'not_found: shipment event'; end if;
    if v_event.projection_status = 'projected' and v_event.commerce_projected_at is not null then
        return to_jsonb(v_event);
    end if;
    if v_event.projection_status <> 'processing' or v_event.projection_claim_token is distinct from p_claim_token then
        raise exception 'conflict: shipment event projection lease mismatch';
    end if;
    update delivery.shipment_events
    set projection_status = case when v_event.projection_attempts >= p_max_attempts then 'manual_review' else 'retry_wait' end,
        projection_next_attempt_at = case when v_event.projection_attempts >= p_max_attempts
            then projection_next_attempt_at else now() + make_interval(secs => p_retry_delay_seconds) end,
        projection_claimed_at = null,
        projection_claimed_by = null,
        projection_claim_token = null,
        projection_last_error = left(btrim(p_error), 2000),
        projection_manual_review_at = case when v_event.projection_attempts >= p_max_attempts then now() else null end
    where id = p_event_id
    returning * into v_event;
    return to_jsonb(v_event);
end;
$$;

create or replace function delivery.read_tracking_summary(
    p_expedition_number text
)
returns table (
    shipment jsonb,
    events jsonb
)
language plpgsql
volatile
security invoker
set search_path = ''
as $$
declare
    v_shipment_id text;
    v_shipment jsonb;
    v_events jsonb;
begin
    -- VOLATILE and the two statements deliberately retain the separate
    -- READ COMMITTED observation points of the former PostgREST requests.
    select
        shipment_row.id,
        pg_catalog.jsonb_build_object(
            'id', shipment_row.id,
            'status', shipment_row.status,
            'latest_event_label', shipment_row.latest_event_label,
            'latest_event_at', shipment_row.latest_event_at
        )
    into v_shipment_id, v_shipment
    from delivery.shipments shipment_row
    where shipment_row.expedition_number = p_expedition_number;

    if not found then
        return query select null::jsonb, '[]'::jsonb;
        return;
    end if;

    select coalesce(
        pg_catalog.jsonb_agg(
            pg_catalog.jsonb_build_object(
                'normalized_status', event_row.normalized_status,
                'occurred_at', event_row.occurred_at,
                'event_label', event_row.event_label,
                'event_date', event_row.event_date,
                'event_time', event_row.event_time,
                'location', event_row.location
            ) order by event_row.occurred_at desc nulls last, event_row.created_at desc
        ),
        '[]'::jsonb
    )
    into v_events
    from delivery.shipment_events event_row
    where event_row.shipment_id = v_shipment_id;

    return query select v_shipment, v_events;
end;
$$;

revoke execute on function delivery.read_tracking_summary(text)
    from public, anon, authenticated;
grant execute on function delivery.read_tracking_summary(text)
    to service_role;

